'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { importTags } = require('./src/tags.js');

test('appends new template tags after current tags', () => {
  assert.deepStrictEqual(importTags(['alpha', 'beta'], ['gamma']), ['alpha', 'beta', 'gamma']);
});

test('skips template tags the user already has', () => {
  assert.deepStrictEqual(importTags(['alpha', 'beta'], ['beta', 'gamma']), ['alpha', 'beta', 'gamma']);
});

test('empty template list leaves current tags unchanged', () => {
  assert.deepStrictEqual(importTags(['alpha'], []), ['alpha']);
});

test('empty current list takes template tags in order', () => {
  assert.deepStrictEqual(importTags([], ['one', 'two']), ['one', 'two']);
});

test('does not mutate its inputs', () => {
  const current = ['alpha'];
  const template = ['beta'];
  importTags(current, template);
  assert.deepStrictEqual(current, ['alpha']);
  assert.deepStrictEqual(template, ['beta']);
});

