'use strict';

// Combines the user's tags with tags copied from a template.
// Judgment call: 'already have' matches case-insensitively, because tags
// are free text typed by users and News next to news would read as dupes.
function importTags(currentTags, templateTags) {
  const have = new Set(currentTags.map((t) => t.toLowerCase()));
  const result = currentTags.slice();
  for (const tag of templateTags) {
    const key = tag.toLowerCase();
    if (!have.has(key)) {
      have.add(key);
      result.push(tag);
    }
  }
  return result;
}

module.exports = { importTags };
